# idea: color-opponent + divisively-normalized Gabor energy spatial pyramid (deterministic V1/V4 front end)
"""
Deterministic, untrained ventral front end. Split the image into opponent channels (luminance L,
red-green RG, blue-yellow BY). On L build a Gaussian pyramid and, at each level, compute
8-orientation quadrature Gabor complex-cell energy; apply cross-orientation divisive normalization
(Heeger) to get contrast-invariant orientation tuning, and separately keep a sqrt-compressed total
energy (contrast magnitude). Add spatially-pooled opponent color and chromatic Gabor edges. All
features are average-pooled onto small per-level grids and concatenated. Per-sample, no learned weights.
"""
import math
import torch
import torch.nn.functional as F

N_ORIENT = 8
WAVELENGTH = 4.0
SIGMA = 2.2
GAMMA = 0.6
GRIDS = (6, 5, 4, 3)          # luminance-Gabor pooling grids per pyramid level (coarser = more position-tolerant)
DIVNORM_C = 0.3               # semi-saturation constant (relative units) for divisive normalization
COLOR_GRIDS = (8, 4)         # opponent-color pooling grids
N_ORIENT_C = 8               # chromatic Gabor orientations


def _noncartesian_bank():
    """Fixed bank of LOCAL non-Cartesian (polar) filters -- concentric, radial, and spiral carriers
    within a Gaussian envelope, in quadrature. V4 is selectively tuned to non-Cartesian gratings
    (Gallant et al.) that Cartesian Gabors cannot represent. Returns (2*T,1,k,k) quadrature kernels
    (T filter types) and T. Deterministic (depends only on constants)."""
    k = int(2 * math.ceil(3 * SIGMA) + 1)
    c = (k - 1) / 2.0
    ys, xs = torch.meshgrid(torch.arange(k) - c, torch.arange(k) - c, indexing="ij")
    r = torch.sqrt(xs ** 2 + ys ** 2)
    th = torch.atan2(ys, xs)
    env = torch.exp(-(r ** 2) / (2 * (SIGMA * 1.3) ** 2))
    specs = []                                                    # (kind, param_a, param_b)
    specs += [("conc", lam, 0) for lam in (4.0, 7.0)]            # concentric rings at 2 frequencies
    specs += [("rad", m, 0) for m in (2, 3, 4)]                  # radial spokes (2,3,4-fold)
    specs += [("spiral", 2, 6.0), ("spiral", 3, 6.0)]           # spirals (angular x radial)
    kernels = []
    for kind, a, b in specs:
        if kind == "conc":
            phase = 2 * math.pi * r / a
        elif kind == "rad":
            phase = a * th
        elif kind == "hyp":
            phase = 2 * math.pi * (xs ** 2 - ys ** 2) / (a ** 2)
        else:
            phase = a * th + 2 * math.pi * r / b
        for off in (0.0, math.pi / 2):
            g = env * torch.cos(phase + off)
            g = g - g.mean()
            g = g / (g.norm() + 1e-8)
            kernels.append(g)
    return torch.stack(kernels).unsqueeze(1), len(specs)


def _fft_polar_bins(h, wf, n_sf, n_ori):
    """(h*wf, n_sf*n_ori) averaging matrix binning the rfft2 magnitude grid into log-spaced radial
    (spatial-frequency) x angular (orientation) bins -- for a compact GLOBAL amplitude-spectrum feature."""
    fy = torch.fft.fftfreq(h).view(h, 1).expand(h, wf)
    fx = torch.fft.rfftfreq(2 * (wf - 1)).view(1, wf).expand(h, wf)
    r = torch.sqrt(fy ** 2 + fx ** 2).reshape(-1)
    ang = torch.atan2(fy.reshape(-1).abs(), fx.reshape(-1))       # [0,pi/2]-ish; real-signal symmetry
    r = r / (r.max() + 1e-8)
    redges = torch.linspace(0, 1, n_sf + 1) ** 2                  # log-ish, dense at low SF
    rbin = torch.clamp(torch.bucketize(r, redges[1:-1]), 0, n_sf - 1)
    obin = torch.clamp((ang / (math.pi / 2 + 1e-6) * n_ori).long(), 0, n_ori - 1)
    cell = rbin * n_ori + obin
    M = torch.zeros(h * wf, n_sf * n_ori)
    M[torch.arange(h * wf), cell] = 1.0
    return M / (M.sum(0, keepdim=True) + 1e-8)


def _gabor_bank_wl(n_orient, wavelength, sigma):
    """Gabor bank with a custom wavelength/sigma (for a dedicated fine-spatial-frequency channel)."""
    k = int(2 * math.ceil(3 * sigma) + 1)
    c = (k - 1) / 2.0
    ys, xs = torch.meshgrid(torch.arange(k) - c, torch.arange(k) - c, indexing="ij")
    kernels = []
    for o in range(n_orient):
        theta = math.pi * o / n_orient
        xr = xs * math.cos(theta) + ys * math.sin(theta)
        yr = -xs * math.sin(theta) + ys * math.cos(theta)
        env = torch.exp(-(xr ** 2 + (GAMMA ** 2) * yr ** 2) / (2 * sigma ** 2))
        for phase in (0.0, math.pi / 2):
            g = env * torch.cos(2 * math.pi * xr / wavelength + phase)
            g = g - g.mean()
            g = g / (g.norm() + 1e-8)
            kernels.append(g)
    return torch.stack(kernels).unsqueeze(1)


def _gabor_bank(n_orient):
    k = int(2 * math.ceil(3 * SIGMA) + 1)
    c = (k - 1) / 2.0
    ys, xs = torch.meshgrid(torch.arange(k) - c, torch.arange(k) - c, indexing="ij")
    kernels = []
    for o in range(n_orient):
        theta = math.pi * o / n_orient
        xr = xs * math.cos(theta) + ys * math.sin(theta)
        yr = -xs * math.sin(theta) + ys * math.cos(theta)
        env = torch.exp(-(xr ** 2 + (GAMMA ** 2) * yr ** 2) / (2 * SIGMA ** 2))
        for phase in (0.0, math.pi / 2):
            g = env * torch.cos(2 * math.pi * xr / WAVELENGTH + phase)
            g = g - g.mean()
            g = g / (g.norm() + 1e-8)
            kernels.append(g)
    return torch.stack(kernels).unsqueeze(1)


def _energy(x, bank, n_orient):
    """(N,1,h,w) -> per-orientation complex-cell energy (N, n_orient, h, w)."""
    k = bank.shape[-1]
    resp = F.conv2d(x, bank, padding=k // 2)
    resp = resp.reshape(x.shape[0], n_orient, 2, resp.shape[-2], resp.shape[-1])
    return torch.sqrt(resp[:, :, 0] ** 2 + resp[:, :, 1] ** 2 + 1e-8)


def _rand_conv(cin, cout, k, gen):
    w = torch.randn(cout, cin, k, k, generator=gen)
    w = w / (w.reshape(cout, -1).norm(dim=1).view(cout, 1, 1, 1) + 1e-8)   # unit-norm fixed-random filters
    return w


def _even_odd(x, bank, n_orient):
    """(N,1,h,w) -> per-orientation even (cos) and odd (sin) Gabor responses, each (N,n_orient,h,w)."""
    k = bank.shape[-1]
    resp = F.conv2d(x, bank, padding=k // 2)
    resp = resp.reshape(x.shape[0], n_orient, 2, resp.shape[-2], resp.shape[-1])
    return resp[:, :, 0], resp[:, :, 1]


def _std_img(x):
    """Per-image, per-channel standardization (per-sample; only that image's spatial stats)."""
    return (x - x.mean(dim=(2, 3), keepdim=True)) / (x.std(dim=(2, 3), keepdim=True) + 1e-5)


def _gc(e, c=DIVNORM_C):
    """Contrast-invariant gain control of an energy stack (N,K,h,w): divide each orientation map by
    the local cross-orientation energy plus a semi-saturation term. Contrast-invariant CARRIERS make
    2nd-order scattering encode texture GEOMETRY (which orientations co-occur) rather than raw contrast."""
    s = (e ** 2).sum(dim=1, keepdim=True)
    return e / torch.sqrt(s + c ** 2 * s.mean(dim=(2, 3), keepdim=True) + 1e-8)


def _ori_gram(e, pool, n):
    """Position-invariant cross-orientation correlation (upper-triangle Gram) of an energy stack
    (N,K,h,w), pooled to a small (pool x pool) grid first so it stays local-ish. Captures WHICH
    orientations co-occur (texture geometry: edges vs corners vs crosshatch), signed-sqrt normalized."""
    ep = F.adaptive_avg_pool2d(e, pool)                               # (N,K,pool,pool)
    K = ep.shape[1]
    flat = ep.reshape(n, K, -1)
    G = torch.bmm(flat, flat.transpose(1, 2)) / flat.shape[-1]        # (N,K,K)
    iu = torch.triu_indices(K, K, device=e.device)
    g = G[:, iu[0], iu[1]]                                            # (N, K(K+1)/2)
    return torch.sign(g) * torch.sqrt(g.abs() + 1e-8)



_PCACHE = {}


def _ppool(x, r, s, gamma=1.6):
    """Module-level foveal POLAR pooling (rings x sectors, finer central rings via gamma>1). Cached."""
    n, C = x.shape[0], x.shape[1]
    key = (x.shape[-2], x.shape[-1], r, s, gamma)
    M = _PCACHE.get(key)
    if M is None or M.device != x.device:
        M = _logpolar_matrix(x.shape[-2], x.shape[-1], r, s, gamma=gamma).to(x.device)
        _PCACHE[key] = M
    return (x.reshape(n, C, -1) @ M).reshape(n, -1)


def _soft_hist(chan, lo, hi, kbins, grids, n):
    """Soft marginal histogram of a per-pixel channel: triangular soft-assignment to kbins value
    bins over [lo,hi], average-pooled per grid. Captures the value DISTRIBUTION per region, not just
    the mean. Per-sample."""
    centers = torch.linspace(lo, hi, kbins, device=chan.device)
    d = (hi - lo) / (kbins - 1)
    w = torch.relu(1.0 - (chan - centers.view(1, kbins, 1, 1)).abs() / d)   # (N,kbins,H,W)
    out = []
    for g in grids:
        if g > 1:
            out.append(_ppool(w, g, g))
        else:
            out.append(F.adaptive_avg_pool2d(w, g).reshape(n, -1))
    return out



def _ring_matrix(h, w, n_rings):
    """(h*w, n_rings) column-normalized averaging matrix over concentric eccentricity rings from the
    image center (equal-area radial bins). Deterministic; depends only on (h, w)."""
    ys = torch.arange(h).float() - (h - 1) / 2
    xs = torch.arange(w).float() - (w - 1) / 2
    yy, xx = torch.meshgrid(ys, xs, indexing="ij")
    r = torch.sqrt(yy ** 2 + xx ** 2).reshape(-1)
    r = r / (r.max() + 1e-6)
    edges = torch.sqrt(torch.linspace(0, 1, n_rings + 1))          # equal-area rings
    rbin = torch.clamp(torch.bucketize(r, edges[1:-1]), 0, n_rings - 1)
    M = torch.zeros(h * w, n_rings)
    M[torch.arange(h * w), rbin] = 1.0
    return M / (M.sum(0, keepdim=True) + 1e-8)


def _mag_ring_matrix(h, w, n_rings, gamma=2.0):
    """(h*w, n_rings) ring-averaging matrix with FOVEALLY-DENSE (cortical-magnification) boundaries:
    inner-ring radii scale as (k/n)^gamma so central eccentricities get many fine rings and the
    periphery few coarse ones -- matching primate cortical magnification / center object bias."""
    ys = torch.arange(h).float() - (h - 1) / 2
    xs = torch.arange(w).float() - (w - 1) / 2
    yy, xx = torch.meshgrid(ys, xs, indexing="ij")
    r = torch.sqrt(yy ** 2 + xx ** 2).reshape(-1)
    r = r / (r.max() + 1e-6)
    edges = torch.linspace(0, 1, n_rings + 1) ** gamma            # dense near fovea (gamma>1)
    rbin = torch.clamp(torch.bucketize(r, edges[1:-1]), 0, n_rings - 1)
    M = torch.zeros(h * w, n_rings)
    M[torch.arange(h * w), rbin] = 1.0
    return M / (M.sum(0, keepdim=True) + 1e-8)


def _logpolar_matrix(h, w, n_rings, n_sectors, gamma=2.0):
    """(h*w, n_rings*n_sectors) averaging matrix over FOVEALLY-DENSE log-polar cells (rings x angular
    wedges). Mean-pooling a channel over these cells is a coarse, center-referenced SHAPE/position
    signature (where features sit around the central object) with cortical-magnification ring spacing."""
    ys = torch.arange(h).float() - (h - 1) / 2
    xs = torch.arange(w).float() - (w - 1) / 2
    yy, xx = torch.meshgrid(ys, xs, indexing="ij")
    r = torch.sqrt(yy ** 2 + xx ** 2).reshape(-1)
    r = r / (r.max() + 1e-6)
    ang = torch.atan2(yy.reshape(-1), xx.reshape(-1))            # [-pi, pi]
    edges = torch.linspace(0, 1, n_rings + 1) ** gamma
    rbin = torch.clamp(torch.bucketize(r, edges[1:-1]), 0, n_rings - 1)
    sbin = torch.clamp(((ang + math.pi) / (2 * math.pi) * n_sectors).long(), 0, n_sectors - 1)
    cell = rbin * n_sectors + sbin
    M = torch.zeros(h * w, n_rings * n_sectors)
    M[torch.arange(h * w), cell] = 1.0
    return M / (M.sum(0, keepdim=True) + 1e-8)


def _logpolar_cells(h, w, n_rings, n_sectors, gamma=1.6):
    """(h*w,) long cell-id map for FOVEALLY-DENSE log-polar cells -- for polar MAX pooling (segment-max
    per cell), which is position-tolerant WITHIN a cell (HMAX C-cell behaviour) with foveal geometry."""
    ys = torch.arange(h).float() - (h - 1) / 2
    xs = torch.arange(w).float() - (w - 1) / 2
    yy, xx = torch.meshgrid(ys, xs, indexing="ij")
    r = torch.sqrt(yy ** 2 + xx ** 2).reshape(-1)
    r = r / (r.max() + 1e-6)
    ang = torch.atan2(yy.reshape(-1), xx.reshape(-1))
    edges = torch.linspace(0, 1, n_rings + 1) ** gamma
    rbin = torch.clamp(torch.bucketize(r, edges[1:-1]), 0, n_rings - 1)
    sbin = torch.clamp(((ang + math.pi) / (2 * math.pi) * n_sectors).long(), 0, n_sectors - 1)
    return (rbin * n_sectors + sbin).long()


_PMAXCACHE = {}


def _ppool_max(x, r, s, gamma=1.6):
    """Foveal POLAR MAX pooling: max of a map (N,C,h,w) within each ring x sector cell -- position-
    tolerant within cells, foveal geometry. Cells with no pixels -> 0."""
    n, C, h, w = x.shape
    key = (h, w, r, s, gamma)
    cell = _PMAXCACHE.get(key)
    if cell is None or cell.device != x.device:
        cell = _logpolar_cells(h, w, r, s, gamma).to(x.device)
        _PMAXCACHE[key] = cell
    idx = cell.view(1, 1, -1).expand(n, C, -1)
    out = x.new_full((n, C, r * s), -1e30)
    out.scatter_reduce_(2, idx, x.reshape(n, C, -1), reduce="amax")
    return out.clamp_min(0.0).reshape(n, -1)


def _recenter(x, E, eps=1e-6):
    """Per-sample object-centering: translate maps x (N,C,h,w) so the ENERGY centroid of E (N,1,h,w)
    sits at the image center, via grid_sample. Per-image only -- no cross-batch statistic."""
    n, _, h, w = x.shape
    dev = x.device
    ys = torch.linspace(-1, 1, h, device=dev).view(1, 1, h, 1)
    xs = torch.linspace(-1, 1, w, device=dev).view(1, 1, 1, w)
    tot = E.sum(dim=(2, 3), keepdim=True) + eps
    cy = (E * ys).sum(dim=(2, 3), keepdim=True) / tot                 # (N,1,1,1) centroid in [-1,1]
    cx = (E * xs).sum(dim=(2, 3), keepdim=True) / tot
    theta = torch.zeros(n, 2, 3, device=dev)
    theta[:, 0, 0] = 1.0; theta[:, 1, 1] = 1.0
    theta[:, 0, 2] = cx.view(n)                                       # sample shifted so centroid->center
    theta[:, 1, 2] = cy.view(n)
    grid = F.affine_grid(theta, x.shape, align_corners=False)
    return F.grid_sample(x, grid, align_corners=False, padding_mode="zeros")


class Model:
    name = "radial-color-form-distribution-model"
    idea = "V4 curvature-at-angular-position shape code (Pasupathy-Connor conjunction)"
    description = ("Opponent color-form backbone (Gabor energy, divnorm, 2nd-order scattering, curvature/"
                   "end-stopping/junctions, hue/color histograms, HMAX colored-shape hierarchy, foveal ring/"
                   "log-polar layout, texture boundaries, DoG blobs, fine-SF V1 map). NEW: the canonical V4 "
                   "shape code -- an OBJECT-CENTERED 2D soft histogram of boundary CURVATURE (convex..concave, "
                   "5 bins) x ANGULAR POSITION around the energy centroid (12 sectors), edge-weighted, at 2 "
                   "scales. This CONJUNCTION of curvature and angular position (Pasupathy-Connor 2001) is a "
                   "true V4 selectivity a linear ridge cannot build from the separate curvature and position "
                   "marginals already present. Replaces the neutral border-ownership block. Per-sample, D_out<10k.")
    insight = ("At the 0.24 plateau, reweighting (signed-sqrt, per-block RMS norm) and adding another "
               "marginal cue (border-ownership) were all neutral-to-negative -- the feature MARGINALS are "
               "saturated. The untried lever is CONJUNCTIONS the linear readout cannot form: curvature-x-"
               "angular-position is the single most-cited V4 shape code and the model has both ingredients "
               "but not their joint tuning. If it lifts test, mid-level CONJUNCTIONS (not more marginals) "
               "are the way forward and I add curvature-x-position for color/other cues next.")
    n_params = (N_ORIENT * 2 * (int(2 * math.ceil(3 * SIGMA) + 1) ** 2)
                + N_ORIENT_C * 2 * (int(2 * math.ceil(3 * SIGMA) + 1) ** 2)
                + 14 * (int(2 * math.ceil(3 * SIGMA) + 1) ** 2)
                + 16 * 2 * (int(2 * math.ceil(3 * 1.4) + 1) ** 2)
                + 32 * (N_ORIENT + 4) * 9 + 48 * 32 * 9 + 64 * 48 * 9 + 64 * 64 * 9)

    def __init__(self):
        self._bankL = None
        self._bankC = None
        self._ring = None
        self._w2 = None
        self._pcache = {}

    def _polar_pool(self, x, r, s, gamma=1.6):
        """Foveal POLAR pooling: average a map (N,C,h,w) over rings x sectors (finer central rings via
        gamma>1) instead of a uniform Cartesian grid -- matches primate foveal magnification + centered
        objects. Same feature count as an r*s-cell grid, better geometry. Matrices cached per map size."""
        n, C = x.shape[0], x.shape[1]
        key = (x.shape[-2], x.shape[-1], r, s, gamma)
        M = self._pcache.get(key)
        if M is None:
            M = _logpolar_matrix(x.shape[-2], x.shape[-1], r, s, gamma=gamma).to(x.device)
            self._pcache[key] = M
        return (x.reshape(n, C, -1) @ M).reshape(n, -1)

    def _branch(self, b1, ws, n):
        """Gain-controlled fixed-random conv colored-shape hierarchy -> compact avg/max readout list.
        Max-pooling between layers (HMAX S->C) for position-tolerant composition."""
        w2, w3, w4, w5 = ws
        a2 = F.relu(F.conv2d(_std_img(b1), w2, padding=1)); a2 = a2 / (4.5 + a2.mean(dim=1, keepdim=True))
        b2 = F.max_pool2d(a2, 2)
        a3 = F.relu(F.conv2d(_std_img(b2), w3, padding=1)); a3 = a3 / (4.5 + a3.mean(dim=1, keepdim=True))
        b3 = F.max_pool2d(a3, 2)
        a4 = F.relu(F.conv2d(_std_img(b3), w4, padding=1)); a4 = a4 / (4.5 + a4.mean(dim=1, keepdim=True))
        b4 = F.max_pool2d(a4, 2)
        a5 = F.relu(F.conv2d(_std_img(b4), w5, padding=1)); a5 = a5 / (4.5 + a5.mean(dim=1, keepdim=True))
        b5 = F.max_pool2d(a5, 2)
        return [
            torch.sqrt(F.adaptive_avg_pool2d(b2, 3) + 1e-6).reshape(n, -1),
            torch.sqrt(F.adaptive_avg_pool2d(b3, 3) + 1e-6).reshape(n, -1),
            torch.sqrt(F.adaptive_avg_pool2d(b3, 1) + 1e-6).reshape(n, -1),
            torch.sqrt(F.adaptive_max_pool2d(b2, 1) + 1e-6).reshape(n, -1),
            torch.sqrt(F.adaptive_max_pool2d(b3, 2) + 1e-6).reshape(n, -1),
            torch.sqrt(F.adaptive_max_pool2d(b4, 1) + 1e-6).reshape(n, -1),
            torch.sqrt(F.adaptive_max_pool2d(b4, 2) + 1e-6).reshape(n, -1),
            torch.sqrt(F.adaptive_max_pool2d(b5, 1) + 1e-6).reshape(n, -1),
        ]

    @torch.no_grad()
    def __call__(self, X):
        X = torch.as_tensor(X)
        dev = X.device
        n = X.shape[0]
        side = round((X.shape[1] / 3) ** 0.5)
        img = X.reshape(n, side, side, 3).float().permute(0, 3, 1, 2)
        R, G, B = img[:, 0:1], img[:, 1:2], img[:, 2:3]
        L = 0.299 * R + 0.587 * G + 0.114 * B
        RG = R - G
        BY = B - 0.5 * (R + G)

        if self._bankL is None or self._bankL.device != dev:
            self._bankL = _gabor_bank(N_ORIENT).to(dev)
            self._bank16 = _gabor_bank(16).to(dev)
            self._bankC = _gabor_bank(N_ORIENT_C).to(dev)
            nc_bank, nc_t = _noncartesian_bank()
            self._bankNC = nc_bank.to(dev)
            self._nc_t = nc_t
            self._bankFine = _gabor_bank_wl(16, 1.7, 1.3).to(dev)
            self._fftM = _fft_polar_bins(side, side // 2 + 1, 6, 8).to(dev)
            self._ring = _ring_matrix(side, side, 5).to(dev)
            self._ring6 = _ring_matrix(side, side, 6).to(dev)
            self._magring = _mag_ring_matrix(side, side, 10, gamma=1.6).to(dev)
            self._logpolar = _logpolar_matrix(side, side, 4, 6, gamma=1.6).to(dev)
            self._logpolar_fov = _logpolar_matrix(side // 2, side // 2, 4, 6, gamma=1.6).to(dev)
            gen = torch.Generator().manual_seed(1234)
            self._w2 = _rand_conv(N_ORIENT + 4, 32, 3, gen).to(dev)
            self._w3 = _rand_conv(32, 48, 3, gen).to(dev)
            self._w4 = _rand_conv(48, 64, 3, gen).to(dev)
            self._w5 = _rand_conv(64, 64, 3, gen).to(dev)

        feats = []
        mag_maps = []
        energy_maps = []
        gc_maps = []
        cur = L
        for lvl, grid in enumerate(GRIDS):
            energy = _energy(cur, self._bankL, N_ORIENT)              # (N,K,h,w)
            e2 = energy ** 2
            denom = e2.mean(dim=1, keepdim=True)                       # (N,1,h,w) mean over orientations
            c2 = DIVNORM_C ** 2 * (denom.mean(dim=(2, 3), keepdim=True) + 1e-8)
            norm = torch.sqrt(e2 / (denom * N_ORIENT + c2 + 1e-8) + 1e-8)   # normalized orientation tuning (compressed)
            mag = torch.log1p(energy.sum(dim=1, keepdim=True))         # log-compressed contrast magnitude
            mag_maps.append(mag)
            energy_maps.append(energy)
            gc_maps.append(norm)                                       # gain-controlled carriers for 2nd-order
            feats.append(F.adaptive_avg_pool2d(norm, grid).reshape(n, -1))
            feats.append(F.adaptive_avg_pool2d(mag, grid).reshape(n, -1))
            if lvl < len(GRIDS) - 1:
                cur = F.avg_pool2d(cur, 2)

        # Second-order scattering: re-filter each GAIN-CONTROLLED per-orientation carrier (one octave
        # coarser) with a coarse Gabor bank and take modulus; contrast-invariant carriers make this
        # encode cross-scale texture/shape GEOMETRY rather than raw contrast magnitude.
        for lvl in (0, 1, 2):
            em = gc_maps[lvl]                                          # (N,K,h,w) gain-controlled
            ds = F.avg_pool2d(em, 2)
            hh, ww = ds.shape[-2], ds.shape[-1]
            s2 = torch.log1p(_energy(ds.reshape(n * N_ORIENT, 1, hh, ww), self._bankC, N_ORIENT_C))
            feats.append(_ppool_max(s2, 2, 2).reshape(n, -1))
        # LARGER-RF 2nd-order scattering: re-filter the fine carriers two octaves coarser -> long-range
        # texture/shape correlations (extended receptive field).
        dsL = F.avg_pool2d(gc_maps[0], 4)
        hh, ww = dsL.shape[-2], dsL.shape[-1]
        s2L = torch.log1p(_energy(dsL.reshape(n * N_ORIENT, 1, hh, ww), self._bankC, N_ORIENT_C))
        feats.append(_ppool_max(s2L, 2, 2).reshape(n, -1))
        dsX = F.avg_pool2d(gc_maps[0], 8)
        hh, ww = dsX.shape[-2], dsX.shape[-1]
        s2X = torch.log1p(_energy(dsX.reshape(n * N_ORIENT, 1, hh, ww), self._bankC, N_ORIENT_C))
        feats.append(_ppool_max(s2X, 2, 2).reshape(n, -1))

        # (cross-orientation Grams removed -- nearly redundant with the co-occurrence + junction streams,
        #  freeing width for denser fine-SF pooling.)

        GP = {8: (6, 8), 6: (4, 8), 4: (3, 6), 2: (2, 3), 1: (1, 1)}
        for grid in (6, 4, 2, 1):                                      # raw luminance + opponent color layout (POLAR)
            feats.append(self._polar_pool(L, *GP[grid]))
        for grid in (6, 4, 2):                                         # local RMS luminance contrast per region (POLAR)
            m1 = self._polar_pool(L, *GP[grid])
            m2 = self._polar_pool(L * L, *GP[grid])
            feats.append(torch.sqrt(torch.clamp(m2 - m1 * m1, min=0.0) + 1e-8))
        for grid in COLOR_GRIDS:                                       # opponent color spatial pyramid (POLAR)
            feats.append(self._polar_pool(RG, *GP[grid]))
            feats.append(self._polar_pool(BY, *GP[grid]))

        # saturation (chroma) and its coarse spatial layout: IT has strong color-object selectivity
        sat = img.amax(dim=1, keepdim=True) - img.amin(dim=1, keepdim=True)
        for grid in COLOR_GRIDS:
            feats.append(self._polar_pool(sat, *GP[grid]))

        # multi-scale chromatic Gabor energy on both opponent channels (2 scales x 2 channels)
        _GP = {8: (6, 8), 7: (5, 8), 6: (4, 8), 5: (4, 6), 4: (3, 6), 3: (2, 6), 2: (2, 3), 1: (1, 1)}
        for scale, grid in ((1, 7), (2, 6), (4, 5), (8, 4)):          # full chromatic energy pyramid (POLAR)
            rg_d = RG if scale == 1 else F.avg_pool2d(RG, scale)
            by_d = BY if scale == 1 else F.avg_pool2d(BY, scale)
            for chan in (rg_d, by_d):
                eC = torch.log1p(_energy(chan, self._bankC, N_ORIENT_C))   # log-compressed chromatic modulus
                feats.append(_ppool_max(eC, *_GP[grid]))

        # chromatic second-order scattering: re-filter GAIN-CONTROLLED opponent modulus maps -> chromatic textures/curvature
        for chan in (RG, BY):
            ec = _gc(_energy(F.avg_pool2d(chan, 2), self._bankC, N_ORIENT_C))   # (N,4,64,64) gain-controlled
            ds = F.avg_pool2d(ec, 2)
            hh, ww = ds.shape[-2], ds.shape[-1]
            s2c = torch.log1p(_energy(ds.reshape(n * N_ORIENT_C, 1, hh, ww), self._bankC, N_ORIENT_C))
            feats.append(_ppool_max(s2c, 2, 2).reshape(n, -1))

        # soft marginal histograms (value distribution per region) of appearance channels
        sat_h = img.amax(dim=1, keepdim=True) - img.amin(dim=1, keepdim=True)
        feats += _soft_hist(L, 0.0, 1.0, 6, (2, 1), n)
        feats += _soft_hist(sat_h, 0.0, 1.0, 5, (2, 1), n)
        feats += _soft_hist(RG, -0.6, 0.6, 6, (2, 1), n)
        feats += _soft_hist(BY, -0.6, 0.6, 6, (2, 1), n)
        # cyclic hue histogram (von-Mises bins x saturation) -- distribution over color angle per region
        hue = torch.atan2(BY, RG)
        KH = 8
        wh = torch.cat([torch.exp(2.5 * torch.cos(hue - 2 * math.pi * k / KH)) for k in range(KH)], dim=1)
        wh = wh / (wh.sum(dim=1, keepdim=True) + 1e-8) * sat_h
        for g in (2, 1):
            feats.append(_ppool(wh, g, g) if g > 1 else F.adaptive_avg_pool2d(wh, g).reshape(n, -1))
        # contrast-magnitude distribution per region (from luminance complex-cell contrast)
        feats += _soft_hist(mag_maps[0], 0.0, 1.8, 5, (2, 1), n)   # fine-scale texture-energy distribution
        feats += _soft_hist(mag_maps[1], 0.0, 1.6, 5, (2, 1), n)
        feats += _soft_hist(mag_maps[2], 0.0, 1.4, 5, (2, 1), n)   # coarse-scale contrast distribution
        # chromatic-energy-strength distribution: log total color-edge energy (RG+BY) at mid scale
        ergb = _energy(F.avg_pool2d(RG, 2), self._bankC, N_ORIENT_C).sum(1, keepdim=True)
        ebgb = _energy(F.avg_pool2d(BY, 2), self._bankC, N_ORIENT_C).sum(1, keepdim=True)
        chroma_mag = torch.log1p(ergb + ebgb)
        feats += _soft_hist(chroma_mag, 0.0, 1.6, 5, (2, 1), n)

        # 2D joint hue x saturation color histogram (polar color-space distribution per region):
        # captures which hues occur at which chroma -- correlations the separate marginals miss.
        KH2, KS2 = 6, 3
        hue2 = torch.atan2(BY, RG)
        hw = torch.stack([torch.exp(2.5 * torch.cos(hue2.squeeze(1) - 2 * math.pi * k / KH2)) for k in range(KH2)], 1)
        hw = hw / (hw.sum(1, keepdim=True) + 1e-8)                    # (N,KH2,H,W) soft hue
        sc = torch.linspace(0.0, 1.0, KS2, device=RG.device)
        sw = torch.relu(1.0 - (sat_h.squeeze(1).unsqueeze(1) - sc.view(1, KS2, 1, 1)).abs() * (KS2 - 1))  # (N,KS2,H,W)
        joint = (hw.unsqueeze(2) * sw.unsqueeze(1)).reshape(n, KH2 * KS2, hue2.shape[-2], hue2.shape[-1])
        for g in (2, 1):
            feats.append(_ppool(joint, g, g) if g > 1 else F.adaptive_avg_pool2d(joint, g).reshape(n, -1))
        # 2D joint hue x luminance histogram (which colors appear at which brightness)
        KL2 = 3
        lc = torch.linspace(0.0, 1.0, KL2, device=RG.device)
        lw = torch.relu(1.0 - (L.squeeze(1).unsqueeze(1) - lc.view(1, KL2, 1, 1)).abs() * (KL2 - 1))
        jhl = (hw.unsqueeze(2) * lw.unsqueeze(1)).reshape(n, KH2 * KL2, hue2.shape[-2], hue2.shape[-1])
        for g in (2, 1):
            feats.append(_ppool(jhl, g, g) if g > 1 else F.adaptive_avg_pool2d(jhl, g).reshape(n, -1))
        # 2D joint luminance x contrast histogram (bright vs dark edges = shading/material)
        contrL = F.interpolate(mag_maps[1], size=hue2.shape[-2:], mode='nearest')
        cwl = torch.relu(1.0 - (contrL.squeeze(1).unsqueeze(1) - torch.linspace(0.0, 1.4, 3, device=RG.device).view(1, 3, 1, 1)).abs() * (2 / 1.4))
        jlc = (lw.unsqueeze(2) * cwl.unsqueeze(1)).reshape(n, KL2 * 3, hue2.shape[-2], hue2.shape[-1])
        for g in (2, 1):
            feats.append(_ppool(jlc, g, g) if g > 1 else F.adaptive_avg_pool2d(jlc, g).reshape(n, -1))

        # multi-scale structure-tensor coherence: local orientation anisotropy (oriented vs isotropic texture)
        sob = torch.tensor([[-1., 0., 1.], [-2., 0., 2.], [-1., 0., 1.]], device=L.device).view(1, 1, 3, 3)
        for sc, g in ((1, 4), (2, 3), (4, 2)):
            Ls = L if sc == 1 else F.avg_pool2d(L, sc)
            gx = F.conv2d(F.pad(Ls, (1, 1, 1, 1), mode='reflect'), sob)
            gy = F.conv2d(F.pad(Ls, (1, 1, 1, 1), mode='reflect'), sob.transpose(-1, -2))
            Jxx = F.avg_pool2d(F.pad(gx * gx, (2, 2, 2, 2), mode='reflect'), 5, stride=1)
            Jyy = F.avg_pool2d(F.pad(gy * gy, (2, 2, 2, 2), mode='reflect'), 5, stride=1)
            Jxy = F.avg_pool2d(F.pad(gx * gy, (2, 2, 2, 2), mode='reflect'), 5, stride=1)
            tr = Jxx + Jyy + 1e-6
            coh = torch.sqrt((Jxx - Jyy) ** 2 + 4 * Jxy ** 2) / tr
            theta2 = 0.5 * torch.atan2(2 * Jxy, Jxx - Jyy)
            stfeat = torch.cat([coh, coh * torch.cos(2 * theta2), coh * torch.sin(2 * theta2)], dim=1)
            feats.append(_ppool_max(stfeat, max(2,g-1), g))

        # ISOPHOTE CURVATURE (V4/IT curvature selectivity, Pasupathy-Connor): the signed curvature of
        # local brightness contours, kappa = (Lx^2 Lyy - 2 Lx Ly Lxy + Ly^2 Lxx) / (Lx^2+Ly^2)^1.5.
        # Straight edges -> 0, curved boundaries/corners -> high |kappa|. Split into CONVEX (kappa>0)
        # and CONCAVE (kappa<0) channels, each weighted by edge strength so curvature is only measured
        # where a contour exists, and polar-MAX pooled (position tolerant), at 3 scales. A shape cue
        # straight Gabor energy and cross-orientation Grams cannot form.
        dxx = torch.tensor([[0., 0., 0.], [1., -2., 1.], [0., 0., 0.]], device=L.device).view(1, 1, 3, 3)
        dyy = dxx.transpose(-1, -2)
        dxy = torch.tensor([[0.25, 0., -0.25], [0., 0., 0.], [-0.25, 0., 0.25]], device=L.device).view(1, 1, 3, 3)
        for sc, g in ((1, 3), (2, 2), (4, 2)):
            Ls = L if sc == 1 else F.avg_pool2d(L, sc)
            Lp = F.pad(Ls, (1, 1, 1, 1), mode='reflect')
            Lx = F.conv2d(Lp, sob) / 8.0
            Ly = F.conv2d(Lp, sob.transpose(-1, -2)) / 8.0
            Lxx = F.conv2d(Lp, dxx)
            Lyy = F.conv2d(Lp, dyy)
            Lxy = F.conv2d(Lp, dxy)
            g2 = Lx * Lx + Ly * Ly
            kappa = (Lx * Lx * Lyy - 2 * Lx * Ly * Lxy + Ly * Ly * Lxx) / (g2 * torch.sqrt(g2 + 1e-8) + 1e-6)
            edge = torch.sqrt(g2 + 1e-8)
            kw = torch.tanh(kappa) * torch.log1p(edge)                # bounded curvature x edge presence
            curv = torch.cat([F.relu(kw), F.relu(-kw)], dim=1)        # convex / concave channels
            feats.append(_ppool_max(curv, g, g + 1))
        # strength rather than saturation -- emphasizes hue AT object boundaries (color-form binding
        # IT is selective for), a color x form interaction the ridge cannot form from separate marginals.
        # MULTI-SCALE gating: fine texture edges vs coarse object boundaries are distinct cues.
        contour_f = mag_maps[0] + F.interpolate(mag_maps[1], size=mag_maps[0].shape[-2:], mode="nearest")
        contour_c = F.interpolate(mag_maps[2], size=mag_maps[0].shape[-2:], mode="nearest")  # coarse boundaries
        KHc = 8
        hue_harm = torch.cat([torch.exp(2.5 * torch.cos(hue - 2 * math.pi * k / KHc)) for k in range(KHc)], dim=1)
        hue_harm = hue_harm / (hue_harm.sum(dim=1, keepdim=True) + 1e-8)   # (N,KHc,H,W) soft hue
        for gate, grids in ((contour_f, (3, 2, 1)), (contour_c, (2, 1))):
            whc = hue_harm * gate                                         # hue gated by contour strength
            for g in grids:
                feats.append(self._polar_pool(whc, max(1,g-1), max(1,g)))
        # signed colored edges: opponent color gated by contour (which colors sit on boundaries)
        for chan in (RG, BY):
            ce = chan * contour_f
            for g in (4, 2):
                feats.append(_ppool(ce, g, g) if g > 1 else F.adaptive_avg_pool2d(ce, g).reshape(n, -1))
        # colored-edge presence map (contour x saturation, log-compressed)
        col_edge = torch.log1p(contour_f * sat_h)
        for g in (4, 2):
            feats.append(_ppool(col_edge, g, g) if g > 1 else F.adaptive_avg_pool2d(col_edge, g).reshape(n, -1))

        # Untrained hierarchical branch: two fixed-random unit-norm convs on the L1 orientation-energy
        # maps (per-image standardization + ReLU + pooling) build compositional mid-level (V2/V4) shape
        # features that complement the color-form statistics. Compact readout -- a deeper/wider/chromatic
        # version overfit (train up, test down); this small luminance branch generalizes and helps.
        # feed a COMPACT color signal alongside luminance orientation energy so the shape hierarchy can
        # build "colored-shape" features (these units are color-selective): chromatic edge-energy sums
        # (where colored edges are) PLUS raw opponent color (what hue is here).
        eRGs = _energy(RG, self._bankC, N_ORIENT_C).sum(dim=1, keepdim=True)
        eBYs = _energy(BY, self._bankC, N_ORIENT_C).sum(dim=1, keepdim=True)
        b1 = F.avg_pool2d(torch.cat([energy_maps[0], eRGs, eBYs, RG, BY], dim=1), 2)   # (N,12,64,64)
        # a single gain-controlled colored-shape hierarchy captures the signal (a 2nd seed just overfits).
        feats += self._branch(b1, (self._w2, self._w3, self._w4, self._w5), n)

        # radial (concentric-ring / eccentricity) layout of color & texture -- objects are center-biased
        csum = torch.log1p(_energy(RG, self._bankC, N_ORIENT_C).sum(1, keepdim=True)
                           + _energy(BY, self._bankC, N_ORIENT_C).sum(1, keepdim=True))
        for chan in (L, RG, BY, sat, csum, mag_maps[0]):
            feats.append(chan.reshape(n, -1) @ self._ring)
        # Radial-ring ENERGY-DISTRIBUTION histograms (leaders' "foveal-ring energy distribution" recipe):
        # soft-bin an energy channel then average each bin within concentric eccentricity rings, giving the
        # DISTRIBUTION of energy vs eccentricity (not just the mean). Bin ranges calibrated to log1p energy.
        lum_e = torch.log1p(energy_maps[0].sum(dim=1, keepdim=True))       # (N,1,128,128) log lum total energy
        for chan, hi in ((lum_e, 2.5), (csum, 2.5), (mag_maps[0], 1.8)):
            centers = torch.linspace(0.0, hi, 5, device=dev)
            d = hi / 4.0
            w = torch.relu(1.0 - (chan - centers.view(1, 5, 1, 1)).abs() / d)   # (N,5,H,W) soft energy bins
            feats.append((w.reshape(n, 5, -1) @ self._ring6).reshape(n, -1))     # (N, 5*6) energy-by-eccentricity

        # HIGH-MAGNIFICATION ten-ring energy-distribution histograms: same soft-binned energy DISTRIBUTION
        # but over FOVEALLY-DENSE cortical-magnification rings (10 rings, dense at center) -- primate
        # cortical magnification + center object bias give the fovea far more units, so finely resolving
        # the central energy/color distribution is high value. Adds a mid-scale contrast channel too.
        lum_e2 = torch.log1p(energy_maps[1].sum(dim=1, keepdim=True))       # mid-scale luminance energy
        for chan, hi in ((lum_e, 2.5), (lum_e2, 2.2), (csum, 2.5), (mag_maps[1], 1.6),
                         (mag_maps[0], 1.8), (sat, 1.0)):
            if chan.shape[-1] != side:
                chan = F.interpolate(chan, size=(side, side), mode='nearest')
            centers = torch.linspace(0.0, hi, 5, device=dev)
            d = hi / 4.0
            w = torch.relu(1.0 - (chan - centers.view(1, 5, 1, 1)).abs() / d)   # (N,5,H,W) soft energy bins
            feats.append((w.reshape(n, 5, -1) @ self._magring).reshape(n, -1))   # (N, 5*10) foveal energy-by-eccentricity
        # signed opponent-color DISTRIBUTION over foveal rings: where warm/cool & blue/yellow sit radially
        # (center object vs peripheral background) -- a color-layout cue the magnitude rings miss.
        for chan, lim in ((RG, 0.6), (BY, 0.6)):
            centers = torch.linspace(-lim, lim, 5, device=dev)
            d = 2 * lim / 4.0
            w = torch.relu(1.0 - (chan - centers.view(1, 5, 1, 1)).abs() / d)
            feats.append((w.reshape(n, 5, -1) @ self._magring).reshape(n, -1))

        # LOG-POLAR cell layout (foveal rings x angular sectors): mean of appearance/energy channels per
        # center-referenced cell -- a coarse SHAPE/position signature of the central object (where edges,
        # color, and contrast sit around the center) that pure radial rings average out angularly.
        for chan in (lum_e, csum, mag_maps[0], L, RG, BY, sat):
            if chan.shape[-1] != side:
                chan = F.interpolate(chan, size=(side, side), mode='nearest')
            feats.append(chan.reshape(n, -1) @ self._logpolar)
        # LOG-POLAR ORIENTED ENERGY (a foveal log-polar HOG): mean of each gain-controlled orientation
        # carrier per log-polar cell -- coarse CONTOUR-SHAPE layout (which way edges point in each cell
        # around the central object), the strongest object-shape cue for IT that scalar energy misses.
        Ecen = energy_maps[0].sum(dim=1, keepdim=True)                # per-image energy for object-centering
        for lvl in (0, 1):
            Ls = L if lvl == 0 else F.avg_pool2d(L, 2 ** lvl)
            g16 = _gc(_energy(Ls, self._bank16, 16))                  # 16-orientation gain-controlled carriers
            if g16.shape[-1] != side:
                g16 = F.interpolate(g16, size=(side, side), mode='nearest')
            feats.append(_ppool_max(_recenter(g16, Ecen), 3, 4))     # OBJECT-CENTERED HOG (coarser = more position tolerance + headroom)
        # CROSS-ORIENTATION co-occurrence (texture/junction geometry): products of the gain-controlled
        # carrier with its ADJACENT and ORTHOGONAL orientation -- high at corners/curves/crossings
        # (multi-ori structure) vs straight edges. Finest scale, polar-MAX pooled (position tolerant).
        g = gc_maps[0]
        feats.append(_ppool_max(torch.sqrt(g * torch.roll(g, 1, dims=1) + 1e-8), 4, 4))
        feats.append(_ppool_max(torch.sqrt(g * torch.roll(g, N_ORIENT // 2, dims=1) + 1e-8), 3, 4))
        # DENSE FINE-SF 16-ORIENTATION V1 MAP (re-implementing a peer island's winning idea, my own way):
        # a dedicated fine-wavelength (2px) 16-orientation Gabor energy map, gain-controlled and
        # retinotopically polar-pooled -- fine, finely-oriented edge structure the coarse 8-orientation
        # wavelength-4 pyramid misses. Replaces the neutral chromatic cross-orientation co-occurrence.
        efine = _gc(_energy(L, self._bankFine, 16), c=0.05)
        feats.append(_ppool_max(efine, 5, 7))
        feats.append(_ppool(torch.log1p(_energy(L, self._bankFine, 16).sum(1, keepdim=True)), 5, 7))  # fine-SF contrast magnitude (denser)
        # FINE-SF PHASE (bar/edge on the fine 2px carriers): combining the two biggest levers -- fine
        # spatial frequency and local phase. Symmetric (fine bar/line) vs antisymmetric (fine edge)
        # energy split on the fine even/odd responses, densely pooled.
        evf, odf = _even_odd(L, self._bankFine, 16)
        symf = (evf.abs() - odf.abs()) / (evf.abs() + odf.abs() + 1e-3)
        ewf = torch.log1p(torch.sqrt(evf * evf + odf * odf + 1e-8))
        feats.append(_ppool_max(F.relu(symf) * ewf, 2, 3))       # fine bar/line
        feats.append(_ppool_max(F.relu(-symf) * ewf, 2, 3))      # fine edge
        # FINE-SF bar polarity: bright vs dark fine bars/lines (sign of the fine even response) --
        # luminance polarity of fine symmetric structure, extending the polarity win to the fine band.
        pef = evf / (torch.sqrt(evf * evf + odf * odf + 1e-8) + 1e-3)
        feats.append(_ppool_max(F.relu(pef) * ewf, 2, 3))        # fine bright bar/line
        feats.append(_ppool_max(F.relu(-pef) * ewf, 2, 3))       # fine dark bar/line
        # GLOBAL FOURIER amplitude spectrum (log-polar SF x orientation bins): a compact whole-image
        # texture/shape signature -- which spatial frequencies and orientations dominate globally, a
        # cue distinct from all the local pooled features. Replaces the lower-value size-tolerant block.
        fmag = torch.log1p(torch.fft.rfft2(L.squeeze(1)).abs()).reshape(n, -1)
        feats.append(fmag @ self._fftM)
        # V4 NON-CARTESIAN gratings (Gallant et al.): local concentric/radial/spiral filter energy --
        # V4 is selectively tuned to polar/hyperbolic patterns that Cartesian Gabors cannot represent.
        # Gain-controlled, polar-MAX pooled (position tolerant), at 2 scales for size coverage.
        for sc, g in ((1, 3), (2, 2)):
            Ls = L if sc == 1 else F.avg_pool2d(L, sc)
            enc = _gc(_energy(Ls, self._bankNC, self._nc_t))
            feats.append(_ppool_max(torch.log1p(enc), g, g + 1))
        # LOCAL PHASE / SYMMETRY type (bar/line vs edge): from even (cos) and odd (sin) Gabor responses,
        # sym = (|even|-|odd|)/(|even|+|odd|) is +1 for symmetric bars/lines, -1 for antisymmetric edges --
        # a distinction the phase-INVARIANT energy discards (V1/V2 have distinct bar and edge cells).
        # Split into symmetric/antisymmetric energy-weighted maps, polar-MAX pooled (position tolerant).
        ev, od = _even_odd(L, self._bankL, N_ORIENT)
        sym = (ev.abs() - od.abs()) / (ev.abs() + od.abs() + 1e-3)
        energyw = torch.log1p(torch.sqrt(ev * ev + od * od + 1e-8))
        feats.append(_ppool_max(F.relu(sym) * energyw, 2, 4))     # symmetric (bar/line) energy
        feats.append(_ppool_max(F.relu(-sym) * energyw, 2, 4))    # antisymmetric (edge) energy
        # SIGNED symmetric polarity: bright bar/line vs dark bar/line (sign of the even response) --
        # luminance polarity of symmetric structure, object/material relevant, absent from |even| above.
        pe = ev / (torch.sqrt(ev * ev + od * od + 1e-8) + 1e-3)
        feats.append(_ppool_max(F.relu(pe) * energyw, 2, 3))      # bright bar/line
        feats.append(_ppool_max(F.relu(-pe) * energyw, 2, 3))     # dark bar/line
        # SIGNED edge polarity: light->dark vs dark->light edges (sign of the odd response) -- which side
        # of a boundary is brighter, a shading / figure-ground cue absent from the unsigned edge split.
        po_ = od / (torch.sqrt(ev * ev + od * od + 1e-8) + 1e-3)
        feats.append(_ppool_max(F.relu(po_) * energyw, 2, 3))     # one edge polarity
        feats.append(_ppool_max(F.relu(-po_) * energyw, 2, 3))    # opposite edge polarity
        # END-STOPPING (hypercomplex cells, V1/V2): oriented energy at a location MINUS the collinear
        # energy at its two neighbours ALONG the bar axis -- high only where a contour TERMINATES (line
        # ends, sharp corners, short features) and low along continuous edges. A documented selectivity
        # distinct from energy, junctions, and curvature. Roll each orientation along its own bar axis.
        E0 = energy_maps[0]
        dst = 3
        ends = []
        for o in range(N_ORIENT):
            th = math.pi * o / N_ORIENT
            dy, dx = int(round(-dst * math.sin(th))), int(round(dst * math.cos(th)))
            Eo = E0[:, o:o + 1]
            flank = 0.5 * (torch.roll(Eo, (dy, dx), (2, 3)) + torch.roll(Eo, (-dy, -dx), (2, 3)))
            ends.append(F.relu(Eo - flank))
        feats.append(_ppool_max(torch.log1p(torch.cat(ends, dim=1)), 2, 2))
        # TEXTURE-DEFINED (2nd-order) BOUNDARIES (V2): edges in the TEXTURE-ENERGY map -- boundaries
        # where local texture/statistics change with no 1st-order luminance edge (a textured region on
        # a smooth ground). Gradient magnitude of the oriented-energy sum at 2 scales, polar-MAX pooled.
        for scb, gb in ((0, 3), (1, 2)):
            tex = torch.log1p(energy_maps[scb].sum(1, keepdim=True))
            txp = F.pad(tex, (1, 1, 1, 1), mode='reflect')
            tgx = F.conv2d(txp, sob)
            tgy = F.conv2d(txp, sob.transpose(-1, -2))
            feats.append(_ppool_max(torch.log1p(torch.sqrt(tgx * tgx + tgy * tgy + 1e-8)), gb, gb + 1))
        # DoG BLOB / center-surround (LGN, retinal): isotropic SPOT detector -- oriented Gabors miss round
        # blobs. Difference of box-blurs approximates a Laplacian-of-Gaussian; split into BRIGHT-blob and
        # DARK-blob channels at 3 scales, polar-MAX pooled (position tolerant). A documented early-visual
        # feature absent from the oriented-energy model.
        for k1, k2, gd in ((3, 7, 3), (7, 15, 2), (15, 31, 2)):
            b1 = F.avg_pool2d(F.pad(L, (k1 // 2,) * 4, mode='reflect'), k1, stride=1)
            b2 = F.avg_pool2d(F.pad(L, (k2 // 2,) * 4, mode='reflect'), k2, stride=1)
            dog = b1 - b2
            feats.append(_ppool_max(torch.cat([F.relu(dog), F.relu(-dog)], dim=1), gd, gd + 1))
        # TEXTURE-BLOB (2nd-order center-surround): DoG on the TEXTURE-ENERGY map -- isolated regions of
        # dense texture (a textured patch surrounded by smooth field, or vice-versa) as blobs. Combines
        # the 2nd-order/texture and blob cues; distinct from luminance blobs and texture BOUNDARIES.
        texE = torch.log1p(energy_maps[0].sum(dim=1, keepdim=True))
        for k1, k2, gd in ((7, 15, 2), (15, 31, 2)):
            t1 = F.avg_pool2d(F.pad(texE, (k1 // 2,) * 4, mode='reflect'), k1, stride=1)
            t2 = F.avg_pool2d(F.pad(texE, (k2 // 2,) * 4, mode='reflect'), k2, stride=1)
            tdog = t1 - t2
            feats.append(_ppool_max(torch.cat([F.relu(tdog), F.relu(-tdog)], dim=1), gd, gd + 1))
        # SPECTRAL SLOPE / sharpness (natural-image scale statistic, material / depth-of-field cue): the
        # per-region log-ratio of fine-scale to coarse-scale oriented energy -- sharp fine-textured
        # surfaces vs smooth/blurred ones. A documented material cue absent from the model.
        fineE = torch.log1p(energy_maps[0].sum(1, keepdim=True))
        coarseE = torch.log1p(F.interpolate(energy_maps[2].sum(1, keepdim=True), size=fineE.shape[-2:], mode='nearest'))
        feats.append(_ppool(fineE - coarseE, 2, 3))
        # PER-REGION SCALE PROFILE: the normalized energy fraction at each of 3 pyramid scales per region
        # -- a compact "which spatial frequencies are active here" texture-scale signature that
        # generalizes the spectral-slope ratio to a full scale distribution.
        e0s = energy_maps[0].sum(1, keepdim=True)
        e1s = F.interpolate(energy_maps[1].sum(1, keepdim=True), size=e0s.shape[-2:], mode='nearest')
        e2s = F.interpolate(energy_maps[2].sum(1, keepdim=True), size=e0s.shape[-2:], mode='nearest')
        tots = e0s + e1s + e2s + 1e-3
        for em in (e0s, e1s, e2s):
            feats.append(_ppool(em / tots, 2, 3))
        # V4 CURVATURE-AT-ANGULAR-POSITION (Pasupathy & Connor 2001): the canonical V4 shape code tunes
        # boundary CURVATURE jointly with the boundary point's ANGULAR POSITION around the object center --
        # a CONJUNCTION a linear ridge cannot form from the separate curvature and position marginals the
        # model already has. Build an OBJECT-CENTERED 2D soft histogram (angular sector x signed-curvature
        # bin), edge-strength weighted, at 2 scales -- a compact global V4 shape signature.
        A_bo, Kc_bo = 12, 5
        for scv in (1, 2):
            Lsv = L if scv == 1 else F.avg_pool2d(L, scv)
            Lpv = F.pad(Lsv, (1, 1, 1, 1), mode='reflect')
            Lxv = F.conv2d(Lpv, sob) / 8.0
            Lyv = F.conv2d(Lpv, sob.transpose(-1, -2)) / 8.0
            Lxxv = F.conv2d(Lpv, dxx); Lyyv = F.conv2d(Lpv, dyy); Lxyv = F.conv2d(Lpv, dxy)
            g2v = Lxv * Lxv + Lyv * Lyv
            kappav = (Lxv * Lxv * Lyyv - 2 * Lxv * Lyv * Lxyv + Lyv * Lyv * Lxxv) / (g2v * torch.sqrt(g2v + 1e-8) + 1e-6)
            edgev = torch.sqrt(g2v + 1e-8)
            kv = torch.tanh(1.5 * kappav)                            # signed curvature in (-1,1)
            hv, wv = Lsv.shape[-2], Lsv.shape[-1]
            ysv = torch.linspace(-1, 1, hv, device=dev).view(1, 1, hv, 1)
            xsv = torch.linspace(-1, 1, wv, device=dev).view(1, 1, 1, wv)
            E2 = F.interpolate(Ecen, size=(hv, wv), mode='bilinear', align_corners=False)
            totv = E2.sum(dim=(2, 3), keepdim=True) + 1e-6
            cyv = (E2 * ysv).sum(dim=(2, 3), keepdim=True) / totv    # object centroid (per image)
            cxv = (E2 * xsv).sum(dim=(2, 3), keepdim=True) / totv
            angv = torch.atan2(ysv - cyv, xsv - cxv)                 # angular position around centroid
            asec = torch.cat([torch.exp(2.0 * torch.cos(angv - 2 * math.pi * k / A_bo)) for k in range(A_bo)], dim=1)
            asec = asec / (asec.sum(dim=1, keepdim=True) + 1e-8)     # (N,A,h,w) soft angular sector
            kcen = torch.linspace(-1, 1, Kc_bo, device=dev)
            kb = torch.relu(1.0 - (kv - kcen.view(1, Kc_bo, 1, 1)).abs() * (Kc_bo - 1) / 2.0)   # (N,Kc,h,w) soft curvature bin
            joint = (asec.unsqueeze(2) * kb.unsqueeze(1)).reshape(n, A_bo * Kc_bo, hv, wv) * edgev
            feats.append(torch.log1p(joint.sum(dim=(2, 3))))        # (N, A*Kc) object-centered curvature-position code

        out = torch.cat(feats, dim=1)
        return out


MODEL = Model()
